import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';
import { parseReleaseManifest, renderXcodeVersionConfiguration, syncXcodeVersion, validateVersionWiring } from './sync-version.mjs';

const manifest = { version: '0.1.0', build: 1, packagingEnabled: false };
const include = '#include "Generated/Version.xcconfig"\n';

test('release manifest validates version, build and a real boolean packaging switch', () => {
  assert.deepEqual(parseReleaseManifest(JSON.stringify(manifest)), manifest);
  assert.equal(parseReleaseManifest(JSON.stringify({ ...manifest, packagingEnabled: true })).packagingEnabled, true);
  for (const version of ['1.2', 'v1.2.3', '1.2.3-beta.1', '01.2.3', '1.2.3\nOTHER = YES']) {
    assert.throws(() => parseReleaseManifest(JSON.stringify({ ...manifest, version })));
  }
  for (const build of [0, -1, 1.2, '1', Number.MAX_SAFE_INTEGER + 1]) {
    assert.throws(() => parseReleaseManifest(JSON.stringify({ ...manifest, build })));
  }
  for (const packagingEnabled of ['false', 0, null, []]) {
    assert.throws(() => parseReleaseManifest(JSON.stringify({ ...manifest, packagingEnabled })));
  }
  for (const invalid of [null, [], { ...manifest, release: true }, { version: '0.1.0', build: 1 }]) {
    assert.throws(() => parseReleaseManifest(JSON.stringify(invalid)));
  }
});

test('generated Xcode settings contain only authoritative app version and build', () => {
  assert.equal(renderXcodeVersionConfiguration(JSON.stringify({ version: '12.34.56', build: 789, packagingEnabled: true })),
    '// Generated by .github/scripts/sync-version.mjs. Do not edit.\nMARKETING_VERSION = 12.34.56\nCURRENT_PROJECT_VERSION = 789\n');
});

test('version checks never write stale or missing generated settings', async (t) => {
  const rootDirectory = await mkdtemp(join(tmpdir(), 'buckle-version-'));
  t.after(() => rm(rootDirectory, { recursive: true, force: true }));
  await mkdir(join(rootDirectory, 'Config/Release'), { recursive: true });
  await writeFile(join(rootDirectory, 'Config/Release/manifest.json'), JSON.stringify(manifest));
  await assert.rejects(syncXcodeVersion({ check: true, rootDirectory }));
  await assert.rejects(readFile(join(rootDirectory, 'Config/Generated/Version.xcconfig')), { code: 'ENOENT' });
  await syncXcodeVersion({ rootDirectory });
  const target = join(rootDirectory, 'Config/Generated/Version.xcconfig');
  assert.equal(await readFile(target, 'utf8'), renderXcodeVersionConfiguration(JSON.stringify(manifest)));
  await syncXcodeVersion({ check: true, rootDirectory });
  await writeFile(target, 'stale');
  await assert.rejects(syncXcodeVersion({ check: true, rootDirectory }));
  assert.equal(await readFile(target, 'utf8'), 'stale');
  await syncXcodeVersion({ rootDirectory });
  await syncXcodeVersion({ check: true, rootDirectory });
});

test('project and base configurations cannot override or omit generated versions', () => {
  validateVersionWiring({ project: '', debug: include, release: include });
  for (const assignment of ['MARKETING_VERSION = 1.2.3;', '"CURRENT_PROJECT_VERSION" = "2";',
    'MARKETING_VERSION[sdk=macos*] = 1.2.3', '"CURRENT_PROJECT_VERSION[arch=arm64]" = "2";']) {
    assert.throws(() => validateVersionWiring({ project: assignment, debug: include, release: include }));
    assert.throws(() => validateVersionWiring({ project: '', debug: include + assignment, release: include }));
  }
  assert.throws(() => validateVersionWiring({ project: '', debug: '', release: include }));
  assert.throws(() => validateVersionWiring({ project: '', debug: include, release: include + include }));
});
